import{z as i,x as o,o as l,c as d,q as t,j as e,D as r,d as a,s,S as B,b as A}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"成本分析","description":"","frontmatter":{"title":"成本分析","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ti-cost-analysis.md","filePath":"llm/ti-cost-analysis.md","lastUpdated":1791063341000}'),p={name:"llm/ti-cost-analysis.md"};function h(D,E,m,u,C,F){const n=o("Mermaid");return l(),d("div",null,[E[2]||(E[2]=t('<h1 id="成本分析" tabindex="-1">成本分析 <a class="header-anchor" href="#成本分析" aria-label="Permalink to &quot;成本分析&quot;">​</a></h1><div class="epigraph"><p>算力账与物理账同构：成本等于单价乘卡时，卡时等于步时乘步数；第一步解剖里的每一毫秒，最后都要在这条乘法里付钱。</p><footer>—— 据 Chinchilla 计算最优口径与大规模训练预算实践整理</footer></div><p><a href="/llm/ti-team-review">上一课</a>解决了人与流程，评审会上最硬的一类决定仍悬着：这场实验值多少钱、这个月机群花在哪了。本课写成本分析。第一课立下的乘法——总账等于步时乘步数——在这里兑现成货币：单价乘卡时。规模与数据怎么分预算是 <a href="/llm/chinchilla">Chinchilla</a> 的口径；本课管的是既定预算之内的记账、归因与省钱。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>成本失明有三种表现。<strong>无单价</strong>：机群对内没有等效卡价，「跑一场实验」的成本靠猜测，于是消融在目标规模上随手开，一次扫描烧掉一个季度的预算。<strong>无归因</strong>：月底账单只有总数，哪个项目、哪场 run、哪类开销（计算、存储、网络）占多少无人能答；省成本的讨论没有抓手。<strong>无学费概念</strong>：失败的 run 从账面上消失——它的卡时确实沉没了，但<a href="/llm/ti-failed-exp-archive">死因档案</a>里没有成本字段，同类失败再犯时，没人知道这次学费交了多少遍。</p><h3 id="记账的三个层次" tabindex="-1">记账的三个层次 <a class="header-anchor" href="#记账的三个层次" aria-label="Permalink to &quot;记账的三个层次&quot;">​</a></h3><p>第一层，<strong>run 级</strong>：每场 run 的卡时按步时积分自动累计，乘等效单价得货币成本，与检查点存储量、网络流量一起写进跟踪库——记账是钩子的产物，不是月底的手工工程。第二层，<strong>项目级</strong>：run 打上项目标签，聚合出各项目的月度消耗与份额执行情况，接调度课的公平份额记账。第三层，<strong>类型级</strong>：把开销拆成计算、存储、网络三类——长跑的账大头在计算，检查点近环与里程碑的存储、数据流水线的跨区流量都单列，否则「省计算」的努力会被存储膨胀吃掉。</p><p><span class="marginnote">量级示例：按等效卡价每小时 2 美元计，256 卡跑一天约 1.2 万美元；一场步时 6 秒、25 万步的训练约 10.7 万卡时、二十余万美元。MFU 从 45% 提到 50%，同样一步的墙钟缩短约一成，整场直接省下两万美元级——利用率就是钱，等数据的空转也是钱。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>成本工程三个动作。其一，<strong>定价</strong>：与财务定一次等效卡价（自建按折旧加电力摊销，租用按市场价加余量），全组统一口径发布——定价的意义不在准，在唯一。其二，<strong>归因</strong>：run 级与项目级的成本报表月度发布，异常项（某项目环比翻倍、某 run 存储占用异常）进评审会议程；成本数据与判读曲线同地位，都是决策依据。其三，<strong>省钱的优先级</strong>：按杠杆排序——利用率（MFU 与数据等待）、实验设计（代理规模消融、早杀死线，动<a href="/llm/ti-hparam-search-eng">搜索工程</a>）、架构与精度（动训练方案本身）。反过来的浪费也要点名：无主 run 的空转、被抢占后从未重排的僵尸作业、检查点保留失控的存储，三类在记账上线第一周就会现形。</p><p><span class="marginnote">术语翻译：等效卡价就是把所有来源的算力折算成同一把尺子——自建的卡把购置费按折旧年数加上电费摊到每一小时，租用的卡直接按合同价，最后都折成一个「每卡每小时多少钱」的数。它的价值不在精确，而在唯一：全组用同一个数，比较与归因才有意义。</span></p>',11)),(l(),e(B,null,{default:r(()=>[s(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22%E9%92%A9%E5%AD%90%3A%20%E6%AD%A5%E6%97%B6%E4%B8%8E%E5%90%9E%E5%90%90%22%5D%20--%3E%20C%5B%22run%20%E7%BA%A7%E5%8D%A1%E6%97%B6%E7%A7%AF%E5%88%86%22%5D%0A%20%20CK%5B%22%E6%A3%80%E6%9F%A5%E7%82%B9%E9%87%8F%20%2F%20%E6%B5%81%E9%87%8F%22%5D%20--%3E%20C%0A%20%20C%20--%3E%20P%5B%22%E4%B9%98%E7%AD%89%E6%95%88%E5%8D%A1%E4%BB%B7%22%5D%0A%20%20P%20--%3E%20R%5B%22run%20%E7%BA%A7%E6%88%90%E6%9C%AC%E5%85%A5%E8%B7%9F%E8%B8%AA%E5%BA%93%22%5D%0A%20%20R%20--%3E%20PR%5B%22%E9%A1%B9%E7%9B%AE%E6%A0%87%E7%AD%BE%E8%81%9A%E5%90%88%3A%20%E6%9C%88%E5%BA%A6%E6%8A%A5%E8%A1%A8%22%5D%0A%20%20PR%20--%3E%20REV%5B%22%E5%BC%82%E5%B8%B8%E9%A1%B9%E8%BF%9B%E8%AF%84%E5%AE%A1%E4%BC%9A%22%5D%0A%20%20PR%20--%3E%20S%5B%22%E7%B1%BB%E5%9E%8B%E5%88%86%E8%A7%A3%3A%20%E8%AE%A1%E7%AE%97%20%2F%20%E5%AD%98%E5%82%A8%20%2F%20%E7%BD%91%E7%BB%9C%22%5D%0A"})]),fallback:r(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A("h2",{id:"机制",tabindex:"-1"},[a("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=A("p",null,[a("按钩子记账有效的机理是"),A("strong",null,"实时性"),a("：月底手工对账发现超支时，钱已花完；run 级积分让每场实验启动前就能给出预估、结束时给出决算，预算成为实验设计的输入而非事后清单。类型分解有效的机理是成本结构随负载变化：消融池的账可能一半在存储（检查点密度高、run 数量大），只盯 MFU 会完全打偏。学费入账的机理是闭环：死因档案带成本字段，「这个方向已经花了多少」成为可查事实，沉没成本不该左右去留，但同类学费的累计额必须左右。")],-1)),E[5]||(E[5]=A("p",null,"省钱的杠杆排序也有机理：利用率与实验设计作用于所有卡时（乘法的底数），架构改动只作用于未来的 run；先动底数，再动因子。",-1)),(l(),e(B,null,{default:r(()=>[s(n,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E5%8F%91%E7%8E%B0%E6%9C%AC%E6%9C%88%E8%B6%85%E6%94%AF%22%5D%20--%3E%20D%7B%22%E8%B6%85%E6%94%AF%E6%9D%A5%E8%87%AA%E5%93%AA%E7%B1%BB%E5%BC%80%E9%94%80%3F%22%7D%0A%20%20D%20--%3E%7C%22%E8%AE%A1%E7%AE%97%22%7C%20U%7B%22MFU%20%E6%98%8E%E6%98%BE%E5%81%8F%E4%BD%8E%3F%22%7D%0A%20%20U%20--%3E%7C%22%E6%98%AF%22%7C%20F%5B%22%E4%BF%AE%E6%95%B0%E6%8D%AE%E7%AD%89%E5%BE%85%E4%B8%8E%E6%B5%81%E6%B0%B4%E7%BA%BF%E7%A9%BA%E8%BD%AC%22%5D%0A%20%20U%20--%3E%7C%22%E5%90%A6%22%7C%20E%5B%22%E7%BC%A9%E5%B0%8F%E6%B6%88%E8%9E%8D%E8%A7%84%E6%A8%A1%20%2F%20%E5%8A%A0%E6%97%A9%E6%9D%80%E6%AD%BB%E7%BA%BF%22%5D%0A%20%20D%20--%3E%7C%22%E5%AD%98%E5%82%A8%22%7C%20CK%5B%22%E6%94%B6%E7%B4%A7%E6%A3%80%E6%9F%A5%E7%82%B9%E4%BF%9D%E7%95%99%E7%AD%96%E7%95%A5%22%5D%0A%20%20D%20--%3E%7C%22%E7%BD%91%E7%BB%9C%22%7C%20NW%5B%22%E5%87%8F%E5%B0%91%E8%B7%A8%E5%8C%BA%E6%95%B0%E6%8D%AE%E6%90%AC%E8%BF%90%22%5D%0A%20%20F%20--%3E%20V%5B%22%E6%94%B9%E5%8A%A8%E5%90%8E%E5%A4%8D%E6%9F%A5%E5%8F%AF%E9%9D%A0%E6%80%A7%E4%B8%8E%E6%9B%B2%E7%BA%BF%22%5D%0A%20%20E%20--%3E%20V%0A%20%20CK%20--%3E%20V%0A%20%20NW%20--%3E%20V%0A"})]),fallback:r(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=t('<p><span class="marginnote">常见误区：初学者容易以为「这场 run 已经花了二十万，现在停下就全亏了」，于是硬撑到结束。实际上已花的卡时无论停不停都收不回来；该比较的是「继续跑还要再花多少」与「它还能带回多少信息」。死因档案给学费记账，正是为了让「同类失败累计交了多少遍」变成可查的事实，而不是靠感觉。</span></p><p><span class="marginnote">直觉类比：类型分解就像家庭记账把支出拆成房租、水电、伙食——只看总账单会以为是伙食超标，拆开才发现是房租悄悄涨了。同理，消融池的账可能一半压在检查点存储上，只盯计算利用率，省钱努力就全打在空气上。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课管既定预算内的记账与优化，不管预算怎么定：训练规模与数据量的计算最优分配用 <a href="/llm/chinchilla">Chinchilla</a> 的口径，立项与采购是组织决策。等效单价是内部尺子，不与外部报价对标——它的用途是比较与归因，不是财务审计。成本优化有边界：压 MFU 压到牺牲数值稳定、砍检查点频率砍到故障回滚半天，是把可见的小钱换成不可见的大钱，成本报表要与分析课的可靠性指标同看。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>成本等于单价乘卡时，卡时等于步时乘步数；第一课的乘法在此兑现为货币。</li><li>记账三层：run 级自动积分、项目级标签聚合、类型级拆计算存储网络。</li><li>等效卡价全组唯一；MFU 与数据等待都是钱，利用率优先于花招。</li><li>死因档案带成本字段，学费累计额可查；僵尸作业与存储失控最先现形。</li><li>出处：据 Chinchilla（Hoffmann et al., 2022）计算口径与大规模训练预算实践整理。</li></ul>',6))])}const g=i(p,[["render",h]]);export{f as __pageData,g as default};
